import json,sys,subprocess,shutil
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from tools.common import ROOT,read_json,utc_now,machine_id,write_json
from mod_nailong.tools.art_contract import portrait_ready
priority=read_json(ROOT/'mod_nailong/data/production-priority.json')['sources']
rows=read_json(ROOT/'mod_nailong/data/generated.json')['portraits']
def counts(items):
 result={}
 for tier,high in [('HIGH',True),('LOW',False)]:
  keys=[k for k,p in priority.items() if bool(p['high_priority'])==high]
  ready=sum(k in items and portrait_ready(items[k]) for k in keys)
  states=Counter(items[k].get('review','unset') if k in items else 'no_current_output' for k in keys)
  result[tier]={'total':len(keys),'ready':ready,'remaining':len(keys)-ready,'percent':round(100*ready/len(keys),4),'states':dict(states)}
 result['all']={'total':len(priority),'ready':sum(x['ready'] for x in result.values())}
 result['all']['percent']=round(100*result['all']['ready']/len(priority),4)
 return result
anchors=[]
for commit in ['e83a98dc41ac67df31f94af66d53a643099f2227','48dae1a221adf8b2bda8a5d52cbcd7dd6395a782','3e30f8b388f47df4aa5037cd2327bf1615844270','5904c607f10c7edcd7ef496f309a971596cc1a2e','73a473458087489c162b56545fbb5eae29b4a073','fae7dfdead342991bffaaa34cb58a28de7f61031']:
 raw=subprocess.run(['git','show',commit+':mod_nailong/data/generated.json'],cwd=ROOT,capture_output=True,check=True).stdout
 data=json.loads(raw);stamp=subprocess.run(['git','show','-s','--format=%cI',commit],cwd=ROOT,capture_output=True,text=True,check=True).stdout.strip()
 anchors.append({'commit':commit,'commit_at_utc':stamp,'LOW_ready':counts(data['portraits'])['LOW']['ready'],'record_observed_at':data.get('observed_at_utc')})
events=[]
for p in (ROOT/'mod_nailong/data/production-window-timings').glob('resume-20261025-large-logical-queue-v11-window*-completed.json'):
 for e in read_json(p)['events']:
  if e['phase']=='image_resolved':events.append(e)
current=counts(rows)
summary={'machine_id':machine_id(),'observed_at_utc':utc_now(),'counts':current,'anchors':anchors,'last_finite_run':{'actual_calls':len(events),'actual_PNGs':sum(not e.get('error') for e in events),'first_return':min(e['observed_at_utc'] for e in events),'last_return':max(e['observed_at_utc'] for e in events)},'free_bytes':shutil.disk_usage(ROOT).free,'scope':'Current canonical ready entries only; staged decisions and external colleague experiment approvals are not included. Percent denominator is every unique catalog source, not asset-reference count. Commit times bound snapshot publication and are not exact review observation timestamps.'}
write_json(ROOT/'runtime/percentage-progress-snapshot-20261026.json',summary)
print(json.dumps(summary,ensure_ascii=True))
